result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/rational.py", "content": """"Exact rational arithmetic implemented from scratch.

Rat(num, den) is always stored normalized: gcd-reduced, den > 0,
zero represented as 0/1. No use of fractions.Fraction here.
"""

from math import gcd


class Rat:
    __slots__ = ("num", "den")

    def __init__(self, num, den=1):
        if not isinstance(num, int) or not isinstance(den, int):
            raise TypeError("Rat numerator and denominator must be ints")
        if den == 0:
            raise ZeroDivisionError("Rat denominator must be nonzero")
        if den < 0:
            num, den = -num, -den
        g = gcd(num, den)
        if g > 1:
            num //= g
            den //= g
        self.num = num
        self.den = den

    # ---- helpers -------------------------------------------------------

    @staticmethod
    def _coerce(other):
        if isinstance(other, Rat):
            return other
        if isinstance(other, int):
            return Rat(other, 1)
        return NotImplemented

    @classmethod
    def from_decimal_str(cls, s):
        """Parse a decimal string like '-12.3400' into an exact Rat."""
        if not isinstance(s, str):
            raise TypeError("from_decimal_str expects a str")
        t = s.strip()
        neg = False
        if t and t[0] in "+-":
            neg = t[0] == "-"
            t = t[1:]
        if t.count(".") > 1:
            raise ValueError("invalid decimal string: %r" % (s,))
        int_part, _, frac_part = t.partition(".")
        if int_part == "" and frac_part == "":
            raise ValueError("invalid decimal string: %r" % (s,))
        if int_part == "":
            int_part = "0"
        if frac_part == "":
            frac_part = "0"
        if not (int_part.isdigit() and frac_part.isdigit()):
            raise ValueError("invalid decimal string: %r" % (s,))
        digits = int(int_part + frac_part)
        scale = 10 ** len(frac_part)
        value = cls(digits, scale)
        return -value if neg else value

    # ---- arithmetic ----------------------------------------------------

    def __add__(self, other):
        other = self._coerce(other)
        if other is NotImplemented:
            return NotImplemented
        # a/b + c/d = (ad + cb) / bd
        return Rat(self.num * other.den + other.num * self.den,
                   self.den * other.den)

    __radd__ = __add__

    def __sub__(self, other):
        other = self._coerce(other)
        if other is NotImplemented:
            return NotImplemented
        return Rat(self.num * other.den - other.num * self.den,
                   self.den * other.den)

    def __rsub__(self, other):
        other = self._coerce(other)
        if other is NotImplemented:
            return NotImplemented
        return other - self

    def __mul__(self, other):
        other = self._coerce(other)
        if other is NotImplemented:
            return NotImplemented
        return Rat(self.num * other.num, self.den * other.den)

    __rmul__ = __mul__

    def __truediv__(self, other):
        other = self._coerce(other)
        if other is NotImplemented:
            return NotImplemented
        if other.num == 0:
            raise ZeroDivisionError("division by zero rational")
        # a/b / c/d = ad / bc  (c != 0 guaranteed above)
        result = Rat(self.num * other.den, self.den * other.num)
        return result

    def __rtruediv__(self, other):
        other = self._coerce(other)
        if other is NotImplemented:
            return NotImplemented
        return other / self

    def __neg__(self):
        return Rat(-self.num, self.den)

    def __pos__(self):
        return self

    def __abs__(self):
        return Rat(abs(self.num), self.den)

    def __pow__(self, n):
        if not isinstance(n, int):
            return NotImplemented
        if n < 0:
            if self.num == 0:
                raise ZeroDivisionError("0 cannot be raised to a negative power")
            return Rat(self.den ** (-n), self.num ** (-n))
        return Rat(self.num ** n, self.den ** n)

    # ---- comparisons ---------------------------------------------------

    def __eq__(self, other):
        other = self._coerce(other)
        if other is NotImplemented:
            return NotImplemented
        return self.num == other.num and self.den == other.den

    def __lt__(self, other):
        other = self._coerce(other)
        if other is NotImplemented:
            return NotImplemented
        return self.num * other.den < other.num * self.den

    def __le__(self, other):
        other = self._coerce(other)
        if other is NotImplemented:
            return NotImplemented
        return self.num * other.den <= other.num * self.den

    def __gt__(self, other):
        other = self._coerce(other)
        if other is NotImplemented:
            return NotImplemented
        return self.num * other.den > other.num * self.den

    def __ge__(self, other):
        other = self._coerce(other)
        if other is NotImplemented:
            return NotImplemented
        return self.num * other.den >= other.num * self.den

    def __hash__(self):
        # Match Fraction's hash so equal values hash equally.
        try:
            dinv = pow(self.den, -1, _HASH_MODULUS)
        except ValueError:
            return abs(self.num) % sys_maxint()  # pragma: no cover
        return hash(hash(abs(self.num)) * dinv % _HASH_MODULUS)

    # ---- misc ------------------------------------------------------------

    def __bool__(self):
        return self.num != 0

    def __repr__(self):
        return "Rat(%d, %d)" % (self.num, self.den)

    def __str__(self):
        if self.den == 1:
            return str(self.num)
        return "%d/%d" % (self.num, self.den)


def sys_maxint():  # pragma: no cover
    import sys
    return sys.maxsize


# Fraction.hash matches this scheme (see CPython Lib/fractions.py).
import sys as _sys
_HASH_MODULUS = _sys.hash_info.modulus
del _sys
